namespace ghidra.app.plugin.core.datamgr.util;




using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

public class DataTypeTreeDeleteTask : Task {

	// if the total number of nodes is small, we won't need to collapse the tree before deleting
	// the nodes to avoid excess tree events
	private static readonly int NODE_COUNT_FOR_COLLAPSING_TREE = 100;
	private Map<DataTypeStoreNode, List<GTreeNode>> nodesByArchive;
	private DataTypeManagerPlugin plugin;
	private int nodeCount;

	private bool hasClosedCategories = false;

	public DataTypeTreeDeleteTask(DataTypeManagerPlugin plugin, List<GTreeNode> nodes) : base("Delete Nodes", true, true, true)
    {
		this.plugin = plugin;
		nodeCount = nodes.size();
		nodes = filterList(nodes);

		nodesByArchive = groupNodeByArchive(nodes);
	}

	private Map<DataTypeStoreNode, List<GTreeNode>> groupNodeByArchive(List<GTreeNode> nodes) {

		Map<DataTypeStoreNode, List<GTreeNode>> archiveNodeMap = new();
		foreach (GTreeNode node in nodes) {
			DataTypeStoreNode archiveNode = ((DataTypeTreeNode) node).getArchiveNode();
			List<GTreeNode> archiveNodeList = archiveNodeMap.computeIfAbsent(archiveNode,
				n => new());

			if (node is CategoryNode) {
				if (!node.isLoaded()) {
					hasClosedCategories = true;
				}
			}

			archiveNodeList.add(node);
		}
		return archiveNodeMap;
	}

	private List<GTreeNode> filterList(List<GTreeNode> nodeList) {
		Set<GTreeNode> nodeSet = new(nodeList);
		List<GTreeNode> filteredList = new();

		foreach (GTreeNode node in nodeSet) {
			if (!containsAncestor(nodeSet, node)) {
				filteredList.add(node);
			}
		}

		return filteredList;
	}

	private bool containsAncestor(Set<GTreeNode> nodeSet, GTreeNode node) {
		GTreeNode parent = node.getParent();
		if (parent == null) {
			return false;
		}

		if (nodeSet.contains(parent)) {
			return true;
		}

		return containsAncestor(nodeSet, parent);
	}

	/* @Override */
	public void run(TaskMonitor monitor) {

		int total = 0;
		foreach (List<GTreeNode> list in nodesByArchive.values()) {
			total += list.size();
		}

		monitor.initialize(total);

		//
		// Note: we collapse the node before performing this work because there is a 
		//       potential for a large number of events to be generated.  Further, if the
		//       given archive node has many children (like 10s of thousands), then the
		//       copious events generated herein could lock the UI.  By closing the node, 
		//       the tree is not invalidating/validating its cache as a result of these
		//       events.
		//
		DataTypesProvider provider = plugin.getProvider();
		DataTypeArchiveGTree tree = provider.getGTree();
		GTreeState treeState = tree.getTreeState();
		bool collapseTree = nodeCount > NODE_COUNT_FOR_COLLAPSING_TREE || hasClosedCategories;
		Program program = plugin.getProgram();
		bool wereEventsEnabled = program.isSendingEvents();
		try {
			program.setEventsEnabled(false);

			if (collapseTree) {
				monitor.setIndeterminate(true);
				collapseArchives(tree);
			}

			Set<Entry<DataTypeStoreNode, List<GTreeNode>>> entries = nodesByArchive.entrySet();
			foreach (Entry<DataTypeStoreNode, List<GTreeNode>> entry in entries) {
				List<GTreeNode> list = entry.getValue();
				DataTypeStoreNode node = entry.getKey();
				deleteNodes(node, list, monitor);
			}
		}
		catch (CancelledException e) {
			// nothing to report
		}
		finally {

			// Allow any events to go out before we restore the tree state so that the tree does 
			// not have to process any events it is not concerned with.
			program.flushEvents();
			program.getDataTypeManager().flushEvents();
			program.setEventsEnabled(wereEventsEnabled);
			if (collapseTree) {
				Swing.allowSwingToProcessEvents();
				tree.restoreTreeState(treeState);
			}
		}
	}

	private void collapseArchives(DataTypeArchiveGTree tree) {
		GTreeNode root = tree.getModelRoot();
		List<GTreeNode> children = root.getChildren();
		foreach (GTreeNode archive in children) {
			tree.collapseAll(archive);
		}
	}

	private void deleteNodes(DataTypeStoreNode archiveNode, List<GTreeNode> list,
			TaskMonitor monitor)
    {
		DataTypeManager dtm = archiveNode.getDataTypeManager();
		dtm.withTransaction("Delete Category/DataType", () => {
			foreach (GTreeNode node in list) {
				monitor.checkCancelled();
				removeNode(node, monitor);
				monitor.incrementProgress(1);
			}
		});
	}

	private void removeNode(GTreeNode node, TaskMonitor monitor) {
		if (node is DataTypeNode) {
			DataTypeNode dataTypeNode = (DataTypeNode) node;
			DataType dataType = dataTypeNode.getDataType();
			DataTypeManager dataTypeManager = dataType.getDataTypeManager();
			dataTypeManager.remove(dataType);
		}
		else {
			CategoryNode categoryNode = (CategoryNode) node;
			Category category = categoryNode.getCategory();
			category.getParent().removeCategory(category.getName(), monitor);
		}
	}
}
